svg.metadata:
flowchart TB
  A["Receive the old refreshToken"]
  B["Load and validate session, account and credential version"]
  C["Prepare the candidate session and token pair"]
  D["One atomic update: consume old refresh and publish successor"]
  E["Recheck credential version; return new token pair"]
  X["Invalid input, lost race or store failure: return failure"]
  A --> B
  B --> C
  C --> D
  D --> E
  B -->|"invalid"| X
  D -->|"conflict / failure"| X
  E -->|"version invalidated"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class E good;
  class X stop;
